  "应用筛选": "Apply filters",
  "请先勾选要编辑的节点": "Select the nodes to edit first",
  "每次最多编辑 100 个节点": "Edit up to 100 nodes at a time",
  "已选择 {0} 个节点：{1}": "Selected {0} nodes: {1}",
  "批量操作": "Bulk action",
  "设置或清空分组": "Set or clear group",
  "增加标签": "Add tags",
  "移除标签": "Remove tags",
  "分组名称，或每行一个标签": "Group name, or one tag per line",
  "所有节点验证通过后一起保存。任一节点资料过期或权限不符，整批均不修改；重新打开后再编辑。暂停仅支持严格租约，不自动退款；允许运行后仍须检查到期时间和 Agent 状态。": "All nodes are validated before saving together. Stale profiles or insufficient permissions prevent the entire batch; reopen and edit again. Pause requires strict leases and does not refund usage. After allowing execution, check expiry and Agent status.",
  "保存选中节点": "Save selected nodes",
  "资料修订": "Profile revision",
  "批量保存完成": "Bulk save completed",
  "批量编辑节点资料": "Bulk edit node profiles",
  "现有租约尚在收敛": "Existing lease is still expiring",
  "运行保护策略": "Runtime protection policy",
  "可用优先（推荐）：控制器离线时继续转发": "Availability first (recommended): forward while the controller is offline",
  "严格租约：按量计费节点": "Strict lease: metered billing nodes",
  "租约窗口 / 秒": "Lease window / seconds",
  "节点归属当前租户。可用优先：控制器离线时按最后配置继续转发，崩溃后约 1 秒恢复；不能阻止复制的节点身份同时运行，控制器离线期间额度不能严格限制，也不支持暂停或到期。严格租约：与控制器失联超过租约窗口会停止转发，崩溃后要等旧租约过期。运行策略创建后固定。注册令牌只显示一次。": "The node belongs to the current tenant. Availability first continues with the last configuration while the controller is offline and recovers about one second after a crash. It cannot prevent copied identities from running concurrently, strictly enforce budgets while offline, or support pause/expiry. Strict leases stop forwarding after the renewal window and wait for the old lease after a crash. This policy cannot change after creation. The enrollment token is shown once.",
  "创建节点": "Create node",
  "请将此令牌保存为节点上的私有文件（权限 0600）。": "Save this token in a private file on the node with permissions 0600.",
  "节点启动命令": "Node startup command",
  "跨机器接入须使用 HTTPS。本机 HTTP 地址仅用于本地验收。": "Cross-host connections require HTTPS. Local HTTP addresses are for local acceptance only.",
