  "与规则自身的限速同时生效，取较严者。立即作用于已有连接，不会断开会话；健康探测不计入。": "Applies alongside per-rule limits; the stricter limit wins. Takes effect immediately on existing connections without disconnecting sessions. Health probes are excluded.",
