  "客户端 TLS 服务器名称（证书模式留空沿用订阅域名）": "Client TLS server name (certificate mode: blank uses the subscription domain)",
  "Reality 握手服务器 host:port": "Reality handshake server host:port",
  "Reality 私钥": "Reality private key",
  "内网 / 回环目的地": "Private / loopback destinations",
  "拒绝（推荐）": "Deny (recommended)",
  "生成客户端凭据": "Generate client credentials",
  "生成 Reality 密钥": "Generate Reality key",
  "节点需要安装受支持的协议引擎。面板负责规则权限、流量账本、配额、限速和目的地 ACL。上方监听地址用于客户端连接；来源 ACL 使用实际客户端 IP。订阅请选择 sing-box JSON 或 mihomo YAML。证书模式须让客户端信任签发 CA。Reality 握手与伪装回落流量也计入配额并受目的地限制；请允许握手服务器地址与端口。来源 ACL 不替代握手前的主机防火墙。": "The node requires a supported protocol engine. The panel manages rule permissions, metering, quotas, rate limits and destination ACLs. Clients connect to the listener above; source ACLs use the actual client IP. Choose sing-box JSON or mihomo YAML subscriptions. Certificate mode requires the client to trust the issuing CA. Reality handshake and camouflage fallback traffic also count toward quota and obey destination restrictions; allow the handshake server address and port. Source ACLs do not replace a host firewall before the handshake.",
  "无效的 MPTCP 策略": "Invalid MPTCP policy",
  "MPTCP 只适用于 TCP，不能用于纯 UDP 规则": "MPTCP applies to TCP only, not UDP-only rules",
  "普通 TCP": "Plain TCP",
  "优先 MPTCP · 允许 TCP 回退": "Prefer MPTCP · Allow TCP fallback",
  "必须协商 MPTCP · 否则拒绝": "Require MPTCP negotiation · Reject otherwise",
  "入口传输": "Inbound transport",
  "出口传输": "Outbound transport",
  "MPTCP 需要 Linux 内核与对端支持。额外路径由节点网络配置决定；协商成功不代表已聚合多条线路。更改入口模式前请先停用并发布规则。": "MPTCP requires Linux kernel and peer support. Additional paths depend on node networking; successful negotiation does not prove multiple links are aggregated. Disable and publish the rule before changing its inbound mode.",
  "规则名称": "Rule name",
  "协议": "Protocol",
  "监听地址": "Listen address",
  "供其他节点连接的地址（跨节点引用时填写）": "Address for other nodes (required for cross-node references)",
  "结束端口（留空只监听一个端口，最多 256 个）": "End port (blank for one port; up to 256)",
  "端口段的目标映射": "Port-range target mapping",
  "全部入口连接同一目标端口": "All inbound ports use the same target port",
  "按入口端口偏移目标端口": "Offset target ports by inbound port",
  "目标分配": "Target selection",
  "加权轮询": "Weighted round robin",
  "来源 IP 哈希": "Source IP hash",
  "最少连接": "Least connections",
  "最低延迟（须启用健康探测）": "Lowest latency (requires health probes)",
  "出口绑定与 DNS 缓存": "Egress binding & DNS cache",
  "出口源 IP（留空由系统选择）": "Source IP (blank lets the system choose)",
  "出口网卡名称（留空由系统选择）": "Network interface (blank lets the system choose)",
  "目标域名解析": "Target DNS resolution",
  "沿用系统解析": "Use system resolver",
  "启用按 TTL 缓存": "Enable TTL-based cache",
  "DNS 服务器 IP:端口，每行一个（留空读取系统配置）": "DNS servers as IP:port, one per line (blank uses system configuration)",
  "缓存响应数上限": "Maximum cached responses",
  "正响应 TTL 上限 / 秒（0 不缓存）": "Positive TTL cap / seconds (0 disables caching)",
  "不存在记录的 TTL 上限 / 秒": "Negative TTL cap / seconds",
  "出口绑定只约束业务连接；绑定失败时配置不会生效。DNS 查询沿用系统路由。缓存遵守响应 TTL，不会延长短 TTL。IPv6 监听只接收 IPv6。": "Egress binding applies only to business connections. A failed bind prevents configuration activation. DNS uses system routing. The cache honors response TTLs without extending short TTLs. IPv6 listeners accept IPv6 only.",
  "入口 TLS 与客户端认证": "Inbound TLS & client authentication",
  "入口证书编号（留空使用普通连接）": "Inbound certificate ID (blank for plain connections)",
  "允许客户端的 CA 编号（留空不要求客户端证书）": "Client CA ID (blank does not require a client certificate)",
  "证书和私钥预先放在节点本地，面板只保存编号。TLS 仅用于 TCP；一条规则的所有出口必须使用相同的安全方式。": "Store certificates and private keys on the node beforehand; the panel stores only their IDs. TLS applies to TCP only. All outbound targets in a rule must use the same security mode.",
  "接收可信上游传递的原始地址（PROXY protocol）": "Accept original addresses from trusted upstream proxies (PROXY protocol)",
  "入口 PROXY 报头": "Inbound PROXY header",
  "要求 v1 · 仅 TCP": "Require v1 · TCP only",
  "要求 v2 · TCP / UDP": "Require v2 · TCP / UDP",
  "要求 v1 或 v2 · 仅 TCP": "Require v1 or v2 · TCP only",
  "允许发送报头的代理 CIDR（每行一个，不能为空）": "Trusted proxy CIDRs (one per line; required)",
  "TLS 加密连接内（须同时启用入口 TLS）": "Inside TLS (requires inbound TLS)",
  "报头字节上限": "Maximum header bytes",
  "接受上一跳的预热连接": "Accept upstream prewarmed connections",
  "不接受 · 报头须在连接超时内到达": "No · Header must arrive within the connection timeout",
  "接受 · 最长等待 30 秒报头再连接目标": "Yes · Wait up to 30 seconds for a header before connecting to the target",
  "启用后必须携带正确报头；直接客户端将被拒绝。来源 ACL 和来源哈希按报头中的客户端地址执行。PROXY 和 CRC32C 不提供身份认证；可信网段应只包含你的代理。UDP 每包都须携带 v2，回复为普通业务数据。": "A valid header is mandatory when enabled; direct clients are rejected. Source ACLs and source hashing use the client address in the header. PROXY and CRC32C do not authenticate peers; trust only your own proxies. Every UDP packet requires v2; replies contain plain application data.",
  "合并配额 / bytes（留空不限，0 禁止流量）": "Combined quota / bytes (blank for unlimited; 0 blocks traffic)",
  "合并速率 / bytes/s（留空不限）": "Combined rate / bytes/s (blank for unlimited)",
  "明确开始新计量周期：旧账保留，重新发放本规则额度；共享预算不重置": "Start a new metering period: preserve the ledger and renew this rule's quota; shared budgets are unchanged",
  "高级：超时、会话上限、到期和来源网段": "Advanced: timeouts, session limits, expiry and source networks",
  "连接超时 / ms": "Connection timeout / ms",
