  "TCP 最大连接": "Maximum TCP connections",
  "UDP 最大会话": "Maximum UDP sessions",
  "到期 / Unix 毫秒（留空永不过期）": "Expiry / Unix milliseconds (blank for no expiry)",
  "允许来源 CIDR（留空允许所有未拒绝来源，每行一个）": "Allowed source CIDRs (one per line; blank allows all non-denied sources)",
  "拒绝来源 CIDR（优先于允许列表，每行一个）": "Denied source CIDRs (one per line; overrides allow list)",
  "允许目的地（IP/CIDR/域名/*.example.com，留空允许所有未拒绝，每行一个）": "Allowed destinations (IP/CIDR/domain/*.example.com; one per line; blank allows all non-denied)",
  "拒绝目的地（优先于允许列表，每行一个）": "Denied destinations (one per line; overrides allow list)",
  "允许目的地端口（443、8000-8080、*，留空允许所有，每行一个）": "Allowed destination ports (443, 8000-8080, *; one per line; blank allows all)",
  "拒绝目的地端口（优先于允许列表，每行一个）": "Denied destination ports (one per line; overrides allow list)",
  "启用规则": "Enable rule",
  "同一规则的所有连接共享额度和速率。速率桶允许 max(64 KiB, 一秒额度) 的突发；这不是跨节点用户总限速。": "All connections in a rule share its quota and rate limit. The rate bucket permits bursts of max(64 KiB, one second of allowance). This is not a cross-node user rate limit.",
