  "Shadowsocks 代理服务（客户端自选目的地）": "Shadowsocks proxy (client-selected destinations)",
  "加密方式": "Encryption method",
  "关闭 · 按下方目标转发": "Off · Forward to the targets below",
  "密钥": "Key",
  "允许访问内网 / 本机地址": "Allow private / local destinations",
  "不允许（推荐）": "Disallow (recommended)",
  "允许 · 客户端可访问本节点所在内网": "Allow · Clients can access the node's private network",
  "生成新密钥": "Generate new key",
  "启用后本规则不设目标：客户端（Shadowrocket、Clash、sing-box、v2rayN 等）在每个连接里指定要访问的网站，本节点直接连接。保存后在规则列表点“分享链接”导入客户端。协议选 TCP + UDP 时客户端的 QUIC、DNS、游戏和语音也经过本节点。2022 方式要求两端时钟误差在 30 秒内。": "With this enabled, the rule has no fixed targets. Clients such as Shadowrocket, Clash, sing-box and v2rayN specify a destination per connection; the node connects directly. After saving, use “Share link” in the rule list to import it. TCP + UDP also carries client QUIC, DNS, games and voice traffic. The 2022 methods require clocks within 30 seconds of each other.",
  "客户端连接的地址（公网 IP 或域名）": "Client connection address (public IP or domain)",
  "端口": "Port",
  "客户端里显示的名称": "Name shown in the client",
  "复制链接": "Copy link",
  "链接已复制。": "Link copied.",
  "客户端先连到入口节点再中转到这里时，请填写入口节点的地址和端口。链接包含密钥，持有者即可使用本节点上网，请只发给使用者本人；需要停用时更换密钥或停用规则。": "If clients connect through an entry node, enter that node's address and port. The link contains a key and grants network access through this node. Share it only with the intended user; rotate the key or disable the rule to revoke access.",
  "分享 {0}": "Share {0}",
  "修订": "Revision",
  "操作者": "Actor",
  "发布此版本": "Publish this version",
  "历史配置已作为新修订发布。账本不回滚。": "Historical configuration published as a new revision. The ledger was not rolled back.",
  "只读": "Read-only",
  "最近 100 次配置修订": "Latest 100 configuration revisions",
  "Basic 用户名和密码必须同时填写": "Basic username and password must both be provided",
  "Bearer 需填写最多 8 个不重复的 SHA-256 十六进制摘要": "Bearer accepts up to 8 distinct hexadecimal SHA-256 digests",
  "HTTP/2 并发隧道上限为 1–4096": "HTTP/2 concurrent tunnel limit must be 1–4096",
  "TCP 缓冲请求为 16384–4194304 字节，留空由系统自动调整": "TCP buffer requests must be 16384–4194304 bytes; blank enables OS autotuning",
  "HTTP/2 CONNECT 入口（TLS / h2c）": "HTTP/2 CONNECT inbound (TLS / h2c)",
  "HTTP/2 服务": "HTTP/2 service",
  "Basic 用户名（可选）": "Basic username (optional)",
  "Basic 密码": "Basic password",
  "Bearer SHA-256 摘要（每行一个，可同时保留新旧令牌）": "Bearer SHA-256 digests (one per line; old and new tokens may coexist)",
  "整条规则的并发隧道上限": "Concurrent tunnel limit for this rule",
  "每方向 TCP 缓冲请求 / bytes（留空自动，手动值需按实际负载验证）": "Requested TCP buffer per direction / bytes (blank for automatic; validate manual values under real load)",
  "生成 Bearer 令牌": "Generate Bearer token",
  "生成令牌需要 HTTPS 或 localhost 面板连接": "Token generation requires HTTPS or a localhost panel connection",
  "请先删除旧摘要，最多保留 8 个": "Remove an old digest first; at most 8 are allowed",
  "令牌原文仅在本次对话框显示，请保存后发给客户端。服务器仅保存摘要。删除旧摘要并发布会关闭已有连接。Basic 和 Bearer 都留空时无需认证；身份与计费归属规则所有者。公网使用下方入口 TLS，可选客户端 CA。h2c 仅供受信网络。HTTP/2 客户端必须支持 CONNECT；curl 使用 --proxy-http2。": "The raw token appears only in this dialog. Save it for the client; the server stores only its digest. Removing an old digest and publishing closes existing connections. Blank Basic and Bearer settings disable authentication; identity and billing belong to the rule owner. Use inbound TLS for public access, with an optional client CA. h2c is for trusted networks only. HTTP/2 clients must support CONNECT; curl uses --proxy-http2.",
  "HTTP CONNECT 入口（TCP）": "HTTP CONNECT inbound (TCP)",
  "HTTP CONNECT 服务": "HTTP CONNECT service",
  "启用 · 客户端指定 CONNECT 目的地": "Enabled · Client selects the CONNECT destination",
  "用户名（留空不认证）": "Username (blank for no authentication)",
  "密码（与用户名同时填写）": "Password (provide together with username)",
  "允许连接内网/回环目的地": "Allow private/loopback destinations",
  "只接受 HTTP/1.x CONNECT；其它方法返回 405。启用认证时要求 Proxy-Authorization: Basic。启用后规则不能有固定目标，协议必须为 TCP。": "Accepts HTTP/1.x CONNECT only; other methods return 405. Authentication requires Proxy-Authorization: Basic. The rule must use TCP and cannot have fixed targets.",
  "HTTP CONNECT 用户名和密码必须同时填写或同时留空": "HTTP CONNECT username and password must both be provided or both blank",
  "客户端连接的地址": "Client connection address",
  "显示名称": "Display name",
  "HTTP CONNECT 链接已复制。": "HTTP CONNECT link copied.",
  "链接包含认证信息；这是 HTTP 代理地址，不是普通网页。": "This link contains credentials. It is an HTTP proxy address, not a web page.",
  "SOCKS5 入口（TCP CONNECT）": "SOCKS5 inbound (TCP CONNECT)",
  "SOCKS5 服务": "SOCKS5 service",
  "启用 · 客户端指定目的地": "Enabled · Client selects the destination",
  "支持 TCP CONNECT 与 UDP ASSOCIATE。使用 UDP 时请把协议设为 TCP + UDP；启用后规则不能有固定目标。用户名和密码要么都留空（无认证），要么都填写。分享链接包含密码，请只发给使用者。": "Supports TCP CONNECT and UDP ASSOCIATE. Use TCP + UDP for UDP traffic. The rule cannot have fixed targets. Provide both username and password, or leave both blank to disable authentication. Share links contain the password; send them only to the intended user.",
  "SOCKS5 用户名和密码必须同时填写或同时留空": "SOCKS5 username and password must both be provided or both blank",
  "SOCKS5 链接已复制。": "SOCKS5 link copied.",
  "链接包含认证信息；需要停用时删除规则或修改用户名/密码。": "This link contains credentials. Delete the rule or change its username/password to revoke access.",
