  "把以下付款编号交给支付网关；网关回调必须携带对原始 JSON 的 HMAC-SHA256 签名。回调成功后订单变为已支付，但不会增加钱包余额。": "Give this payment ID to the gateway. Its callback must include an HMAC-SHA256 signature of the raw JSON. A successful callback marks the order paid without crediting the wallet.",
