  "全局公告只有系统管理员可以创建；租户管理员只能发布到自己的租户。时间按浏览器本地时区输入，服务端保存 Unix 毫秒。": "Only system administrators can create global announcements. Tenant administrators can publish only to their tenant. Times use the browser's local timezone and are stored as Unix milliseconds.",
