  "公告已删除。": "Announcement deleted.",
  "仅系统管理员可见": "System administrators only",
  "DNS 服务商令牌可修改外部 DNS，因此只向系统管理员开放。": "DNS provider tokens can modify external DNS, so access is restricted to system administrators.",
  "DNS 服务商": "DNS providers",
  "保存 Cloudflare 兼容 API 或 DNS Webhook 接收端的地址和凭据。令牌和 Secret 可逆保存以调用服务商，接口只显示是否已设置；仅系统管理员可读写。": "Stores the endpoint and credentials of a Cloudflare-compatible API or a DNS webhook receiver. Tokens and secrets are stored reversibly for provider calls; the API reports only whether one is set. System administrators only.",
  "＋ 新增服务商": "＋ Add provider",
  "还没有 DNS 服务商": "No DNS providers yet",
  "先添加服务商，再创建区域和托管记录。": "Add a provider, then create zones and managed records.",
  "API 地址": "API endpoint",
  "令牌": "Token",
  "DNS 区域": "DNS zones",
  "区域名是服务商的 zone 名称或 ID。观察模式只读取服务商并报告差异；应用模式只管理由本平台创建、带 relay 标记的记录。": "Use the provider's zone name or ID. Observe mode reads and reports differences. Apply mode manages only records created by this platform with a relay marker.",
  "＋ 新增区域": "＋ Add zone",
  "还没有 DNS 区域": "No DNS zones yet",
  "添加区域后可以创建 A/AAAA/CNAME 托管记录并执行一次同步。": "Add a zone to create managed A/AAAA/CNAME records and run a sync.",
  "区域": "Zone",
  "服务商": "Provider",
  "模式": "Mode",
  "最少保留": "Minimum retained",
  "记录": "Records",
  "立即同步": "Sync now",
  "托管记录 · {0}": "Managed records · {0}",
  "每条记录带 relay 标记。删除记录时应用模式会同时删除服务商记录；观察模式只删除本地记录。健康摘除只在节点心跳新鲜且至少一个目标健康时保留记录。": "Each record has a relay marker. In apply mode, deletion also removes the provider record; observe mode deletes only the local record. Health gating retains records only while the node heartbeat is fresh and at least one target is healthy.",
  "＋ 新增记录": "＋ Add record",
  "还没有托管记录": "No managed records yet",
  "创建 A/AAAA/CNAME 记录，然后执行“立即同步”。": "Create A/AAAA/CNAME records, then select “Sync now”.",
  "健康摘除": "Health gating",
  "服务商记录": "Provider record",
  "错误": "Error",
  "服务商类型": "Provider type",
  "Cloudflare 兼容 API": "Cloudflare-compatible API",
  "API 基础地址": "API base URL",
  "令牌（留空保留原值）": "Token (blank keeps the current value)",
  "API 令牌": "API token",
  "DNS Webhook（签名记录集）": "DNS webhook (signed record sets)",
  "接收端 URL": "Receiver URL",
  "Secret（至少 32 字节）": "Secret (at least 32 bytes)",
  "Secret（留空保留原值）": "Secret (blank keeps the current value)",
  "区域（多个用逗号或空格分隔）": "Zones (separate with commas or spaces)",
  "请求超时（秒）": "Request timeout (seconds)",
  "Webhook：控制器把每个名称和类型的完整值集合以签名 JSON 发送到接收端（HMAC-SHA256，按 ZFC DNS Webhook 协议 v1 的公开说明），只在接收端确认写入后算成功，不跟随重定向。Secret 至少 32 字节，接口不会返回原文；HTTP 只允许回环地址。DNS 区域只能使用这里列出的域名。": "Webhook: the controller sends the complete value set of each name and type to the receiver as signed JSON (HMAC-SHA256, following the public description of the ZFC DNS webhook protocol v1). A change counts only once the receiver confirms it was applied, and redirects are not followed. The secret needs at least 32 bytes and is never returned; HTTP is allowed only for loopback addresses. DNS zones can only use the domains listed here.",
  "接收端接受了签名的 ping。测试不验证 DNS 写入权限，也不证明记录已经生效。": "The receiver accepted the signed ping. The test does not check DNS write access or prove that records are live.",
  "Webhook 区域的记录名称必须是区域内的完整域名（例如 edge.example.com）。同名同类型的值作为一个完整集合发送，TTL 取其中最低值；不支持 Cloudflare 代理。": "Records in a webhook zone need a full name inside the zone (for example edge.example.com). Values with the same name and type are sent as one complete set with the lowest of their TTLs; Cloudflare proxying is not available.",
  "令牌只应授予 DNS 编辑权限；接口不会返回令牌原文。HTTP 只允许回环地址用于本机测试。": "Grant only DNS editing permissions. The API never returns the raw token. HTTP is allowed only for loopback addresses during local testing.",
  "保存服务商": "Save provider",
  "添加服务商": "Add provider",
  "DNS 服务商已保存。": "DNS provider saved.",
  "编辑 DNS 服务商 · {0}": "Edit DNS provider · {0}",
  "新增 DNS 服务商": "Add DNS provider",
  "区域名称 / ID": "Zone name / ID",
  "最少保留记录数": "Minimum records to retain",
  "观察模式适合先核对现有记录。应用模式只创建/更新/删除本平台带 relay 标记的记录，不会接管同名的外部记录。": "Use observe mode to inspect existing records first. Apply mode creates/updates/deletes only relay-marked records from this platform and does not take over external records with the same name.",
  "保存区域": "Save zone",
  "添加区域": "Add zone",
  "DNS 区域已保存。": "DNS zone saved.",
  "编辑 DNS 区域 · {0}": "Edit DNS zone · {0}",
  "新增 DNS 区域": "Add DNS zone",
  "记录名称": "Record name",
  "内容（IP 或 CNAME）": "Content (IP or CNAME)",
  "TTL（秒）": "TTL (seconds)",
  "Cloudflare 代理": "Cloudflare proxy",
  "不代理": "DNS only",
  "代理": "Proxied",
  "入口健康摘除节点": "Inbound health-gating node",
  "不启用": "Not enabled",
  "健康摘除规则 ID（可选）": "Health-gating rule ID (optional)",
  "健康摘除设置": "Health-gating settings",
  "保留现有设置": "Keep current settings",
  "清除健康摘除": "Clear health gating",
  "应用模式同步后会写入服务商；观察模式只显示“将创建/将更新”。CNAME 内容必须是主机名，A/AAAA 内容必须是 IP。填写节点和规则 ID 后，节点心跳超过 90 秒或没有健康目标时，应用模式会摘除该记录；恢复后自动重建。": "Apply mode writes to the provider on sync; observe mode reports proposed creates/updates only. CNAME content must be a hostname; A/AAAA content must be an IP. With a node and rule ID, apply mode removes records if the heartbeat is over 90 seconds old or no targets are healthy, then recreates them after recovery.",
  "保存记录": "Save record",
  "添加记录": "Add record",
  "DNS 记录已保存；执行“立即同步”后写入服务商。": "DNS record saved. Select “Sync now” to write it to the provider.",
  "编辑 DNS 记录 · {0}": "Edit DNS record · {0}",
  "新增 DNS 记录": "Add DNS record",
  "{0}：观察 {1} 条，创建 {2}，更新 {3}，删除 {4}，未变 {5}，保留 {6}，错误 {7}。": "{0}: observed {1}, created {2}, updated {3}, deleted {4}, unchanged {5}, retained {6}, errors {7}.",
  "动作": "Action",
