  "阈值": "Threshold",
  "连续次数": "In a row",
  "除目标不可用、配置拒绝和节点离线外，还可以按阈值通知节点资源、节点到期、共享额度和 DNS 同步问题。默认全部关闭；问题消失后自动恢复。": "Besides unavailable targets, rejected configurations and offline nodes, alerts can cover node resources, node expiry, shared budgets and DNS sync by threshold. All are off by default, and each resolves on its own when the problem clears.",
  "节点 CPU 使用率": "Node CPU usage",
