  "用户": "User",
  "跨节点共享额度": "Cross-node shared budgets",
  "已用 + 尚未归还的预留不能超过总额度。同一笔流量受适用的用户、租户和节点额度共同约束。": "Used quota plus outstanding reservations cannot exceed the total budget. Each transfer is constrained by all applicable user, tenant and node budgets.",
  "＋ 创建额度": "＋ Create budget",
  "控制器已从备份恢复，新增额度分配暂停。恢复完整的预留记录前，系统不会重复发放旧备份中遗漏的额度。": "The controller was restored from a backup. New allocations are paused until reservation history is fully recovered, preventing duplicate allocation of reservations missing from the backup.",
  "为多个入口设置一个总额度": "Set one total budget for multiple inbounds",
  "创建前先暂停该范围内的规则，并确认所有相关节点已应用；之后重新启用规则，系统会自动绑定额度。": "Pause rules in this scope and confirm every affected node has applied the change before creating a budget. Re-enable the rules afterward; budgets attach automatically.",
  "名称 / 范围": "Name / scope",
  "总额度": "Total budget",
  "已上报用量": "Reported usage",
  "尚未归还预留": "Outstanding reservations",
  "可分配": "Available to allocate",
  "节点按需领取预留。全节点会话空闲或正常停机后可归还未用部分；严格节点保留原状态且交接历史连续时，重启会先核对并恢复预留；旧备份或无法确认的部分继续占额。预留明细显示当前记录，增加总额度不会清零已有账。": "Nodes reserve quota on demand. Unused quota can return when all node sessions are idle or on clean shutdown. Strict nodes with original state and continuous handoff history reconcile and recover reservations before restarting. Old backups or uncertain usage remain reserved. Increasing the total does not reset existing accounting.",
  "预留明细": "Reservation details",
  "调整额度": "Adjust budget",
  "未归还部分可能包含尚未上报的消费，不能直接当作可退款余额。此列表按页读取当前记录；有变化时重新打开刷新。": "Outstanding reservations may contain unreported consumption and are not refundable balances. This paginated list shows current records; reopen to refresh after changes.",
  "预留明细 · ": "Reservation details · ",
  "加载中…": "Loading…",
  "节点 / 运行": "Node / run",
  "预留编号": "Reservation ID",
