  "强调色用于导航和主要操作；卡片与图表使用固定的配色，正常、警告与错误保留固定的状态色和文字。": "Accent colors style navigation and primary actions. Cards and charts use their own fixed colors, and healthy, warning and error states keep their own colors and labels.",
