  "尚无近期 Agent 回报。注册并启动节点，或检查已有 Agent 的连接；发布启用的规则后显示期望转发路径。": "No recent Agent reports. Enroll and start a node, or check an existing Agent connection. Enabled rules display the expected forwarding paths.",
