  "{0} 个目标": "{0} targets",
  "{0} 会话": "Sessions {0}",
  "{0} 的监听地址": "Listen address on {0}",
  "「转发规则」的“全部转发”从客户端展示整条连接，“按服务器”列出一台服务器上运行的规则；两者是同一份配置。「规则模板」保存可复用的规则，可直接新建或从现有规则另存。": "In Forwarding rules, “All forwarding” shows each connection end to end from the client, and “By server” lists the rules running on one server; both show the same configuration. Rule templates store reusable rules; create one directly or save an existing rule as a template.",
  "一台服务器上的监听端口和服务。多跳转发会在经过的每台服务器上各有一条规则；完整路线见「全部转发」。": "Listeners and services on one server. A multi-hop forwarding has one rule on each server it passes through; see “All forwarding” for the full route.",
  "下面是服务器校验后的变更。发布会同时提交期望配置；节点应用结果请在「转发规则」页逐项确认。": "These are the changes after server validation. Publishing submits the desired configuration; confirm each node's result on the Forwarding rules page.",
  "不设置": "Not set",
  "与当前比较": "Compare with current",
  "严格租约 · 恢复等待": "Strict lease · Waiting to recover",
