  "从模板创建": "Create from template",
  "位置": "Location",
  "位置与资料": "Location & profile",
  "位置名称": "Location name",
  "位置来自节点资料；连线是规则声明的下一跳，颜色为该段最新探测结果。拖动地球可旋转，点击节点可定位。": "Locations come from node profiles. Lines follow each rule's declared next hop and are colored by that hop's latest probe result. Drag to rotate the globe; click a node to focus it.",
  "使用": "Use",
  "保存模板": "Save template",
  "健康": "Healthy",
  "先选择这条转发经过几台服务器、提供什么服务。下一步选择服务器，地址和端口自动填写；发布前可以预览完整路径。": "First choose how many servers this forwarding passes through and what service it provides. Next, pick the servers; addresses and ports are filled in automatically, and you can preview the full path before publishing.",
  "全球节点": "Global nodes",
  "全部转发": "All forwarding",
  "其他位置 · 手动填写坐标": "Other location · Enter coordinates",
  "内置向导（单台或多跳的端口转发、Shadowsocks）在「转发规则」的“新建转发”里，会自动分配地址和端口。": "The built-in wizards (single-server or multi-hop port forwarding and Shadowsocks) are under “New forwarding” in Forwarding rules and assign addresses and ports automatically.",
