  "同一份转发配置，按服务器列出它上面运行的监听端口和服务。": "The same forwarding configuration, listing the listeners and services running on each server.",
  "名称 / 说明": "Name / description",
  "回滚到此版本": "Roll back to this version",
  "在「规则模板」页新建模板，或在规则列表中点击“存为模板”。": "Create a template on the Rule templates page, or click “Save as template” in a rule list.",
