  "最近 24 小时没有告警": "No alerts in the last 24 hours",
  "每个月的上行与下行合计。": "Upload and download per month.",
  "每行一个节点，色条从告警出现画到恢复；仍未恢复的延续到现在。恢复记录保存在控制器内存中，控制器重启后重新记录。": "One row per node; each bar runs from when an alert opened to when it recovered, and open alerts run to now. Recovered alerts are kept in controller memory and start over after a controller restart.",
  "流量最多的 12 条规则，共 {0} 条。多跳转发在经过的每台服务器上各计一次。": "The 12 busiest of {0} rules. Multi-hop forwarding is counted once on each server it passes through.",
  "目标不可用、配置拒绝或节点离线时，这里会按节点显示每次告警持续了多久。": "When a target is unavailable, a configuration is rejected or a node goes offline, this shows how long each alert lasted, per node.",
  "目标可用比例": "Targets available",
  "表格": "Table",
  "设置位置": "Set locations",
  "设置节点位置": "Set node locations",
  "还没有节点设置位置": "No node has a location yet",
  "送达 {0} / 共 {1}": "Delivered {0} of {1}",
  "选择每个节点所在的城市，保存后显示在总览地球上。列表中没有的城市，可在节点资料中手动填写坐标。": "Choose the city each node is in; saved nodes appear on the Overview globe. For a city not in the list, enter coordinates in the node's profile.",
