  "平均建立 {0}": "Average setup {0}",
  "成功 {0}": "Success {0}",
  "按规则声明的下一跳绘制；连线颜色取该段最新探测结果与最近 1 小时真实连接中较差的一项，标注为探测往返与连接成功率。点击节点查看规则。": "Paths follow declared next-hop rules. Each link takes the worse of its latest probe result and its real connections in the last hour, labelled with probe round trip and connection success. Select a node to view its rules.",
  "控制器没有返回连接记录。": "The controller returned no connection history.",
  "最近 1 小时真实 TCP 连接：{0}": "Real TCP connections in the last hour: {0}",
  "最近 24 小时 · 每格 15 分钟 · 仅 TCP": "Last 24 hours · 15 minutes per cell · TCP only",
