  "最近 {0} · {1}。只计 TCP 到目标的连接。": "Last {0} · {1}. Counts TCP connections to targets only.",
  "最近 {0} · 全部节点合计。": "Last {0} · All nodes combined.",
  "最近 {0} · 全部节点合计，多跳流量逐跳计入。": "Last {0} · All nodes combined; multi-hop traffic counts at each hop.",
