  "最近 1 小时入站 TCP 连接建立（TLS、PROXY、WebSocket）：{0}": "Inbound TCP setup in the last hour (TLS, PROXY, WebSocket): {0}",
  "看真实连接": "Watch real connections",
  "转发规则页每段箭头显示最近 1 小时真实 TCP 连接的成功率：第一段是入口的入站建立，之后是各服务器拨号到下一跳。展开路径可查看 24 小时或 7 天的逐段记录并导出 CSV；总览可把趋势切换为 24 小时或 7 天。": "On Forwarding rules, each arrow shows the success of real TCP connections in the last hour: the first is the entry's inbound setup, then each server's dials to its next hop. Expand a path for 24-hour or 7-day per-hop history and a CSV export; Overview can switch its trends to 24 hours or 7 days.",
  "逐段真实连接与 7 天历史": "Per-hop real connections and 7-day history",
  "Relay 诊断 · {0} · 控制器 {1}": "Relay diagnostics · {0} · controller {1}",
  "diagnose report troubleshoot export support speed test bandwidth throughput cloudflare 诊断 排障 报告 导出 测速 速度 带宽 全球测速": "diagnose report troubleshoot export support speed test bandwidth throughput cloudflare",
  "log journal tail error 日志 实时 错误": "log journal tail error",
  "{0} 分钟": "{0} min",
