  "已移除。": "Removed.",
  "带宽 {0}": "Bandwidth {0}",
  "开启后，左侧出现「跨面板共享」页。共享方的节点会多出由共享生成的规则，这些规则只能在共享页修改；撤销后节点立即删除它们，对方的密钥失效。接收方每分钟向共享方同步一次。": "When on, a Cross-panel sharing page appears on the left. The owner's node gets rules generated from each share, which change only on the sharing page; revoking removes them from the node at once and the receiver's key stops working. Receivers sync with the owner every minute.",
  "总带宽 / Mbit/s（留空不限速）": "Total bandwidth / Mbit/s (empty means unlimited)",
  "总流量 / GiB（留空不限；建好后只能修改，不能取消或新加）": "Total traffic / GiB (empty means unlimited; after creation it can change but not be removed or added)",
  "把一台节点上的一段端口交给另一个面板使用。对方只能在这段端口里建规则；带宽、流量、到期时间和允许的来源由你决定。规则由本面板生成，对方无法放宽。": "Give another panel a port range on one of your nodes. The receiver can create rules only inside it; you decide the bandwidth, traffic, expiry and allowed sources. This panel builds the rules, so the receiver cannot widen them.",
  "把一台节点上的一段端口共享给另一个 Relay 面板，或接收其他面板共享的端口。对方用一次性邀请码接入，得到自己的密钥；带宽、流量、到期时间和允许的来源由共享方决定，对方无法放宽。": "Share a port range on one of your nodes with another Relay panel, or receive ports shared by other panels. The receiver joins with a one-time invite code and gets its own key; the owner decides bandwidth, traffic, expiry and allowed sources, and the receiver cannot widen them.",
  "把节点上的一段端口共享给另一个面板，或接收其他面板共享的端口。对方用邀请码接入，限制由共享方决定。": "Share a port range on a node with another panel, or receive ports shared by other panels. Receivers join with an invite code; the owner sets the limits.",
  "把邀请码发给对方面板的管理员，对方在「跨面板共享 → 输入邀请码」中粘贴即可接入。邀请码只能使用一次，有效至 {0}。关闭后无法再次查看，需要时可以重新生成。": "Send the invite code to the other panel's administrator, who pastes it under Cross-panel sharing → Enter invite code. It works once and is valid until {0}. It cannot be shown again after you close this; create a new one if needed.",
  "接入": "Join",
  "提交规则": "Submit rule",
  "撤销「{0}」？节点会删除对方的全部规则，对方的密钥立即失效。撤销后不能恢复，只能新建共享。": "Revoke “{0}”? The node deletes all of the receiver's rules and its key stops working at once. This cannot be undone; create a new share instead.",
  "收到的共享 · {0}": "Received share · {0}",
  "新建共享": "New share",
  "新建共享，选择节点和端口范围，再把邀请码发给对方面板的管理员。": "Create a share, choose a node and port range, then send the invite code to the other panel's administrator.",
  "暂停「{0}」？对方的规则会停用，直到你恢复。": "Pause “{0}”? The receiver's rules stop until you resume.",
  "最近同步 {0}，每分钟自动同步。": "Last synced {0}; syncs every minute.",
  "最近访问 {0}": "Last contact {0}",
  "本面板会用邀请码向对方面板换取自己的密钥。邀请码只能使用一次。": "This panel trades the invite code with the owner panel for its own key. An invite code works once.",
  "来源 {0}": "Sources {0}",
  "来自 {0} · 连接 {1} 端口 {2}–{3}": "From {0} · connect to {1} ports {2}–{3}",
  "每分钟自动同步。": "Syncs every minute.",
  "没有规则。": "No rules.",
  "流量 {0}": "Traffic {0}",
  "添加规则 · {0}": "Add rule · {0}",
  "由客户端决定": "Chosen by the client",
  "目标地址（每行一个，主机:端口）": "Targets (one per line, host:port)",
  "禁止访问的目的地（每行一个域名、IP 或网段，可选）": "Blocked destinations (one domain, IP or range per line; optional)",
  "移除「{0}」？本面板会删除这个共享和它的密钥；对方节点上的规则不受影响，需要对方撤销。": "Remove “{0}”? This panel forgets the share and its key; the rules on the owner's node stay until the owner revokes them.",
  "端口（{0}–{1}）": "Port ({0}–{1})",
  "等待对方接入": "Waiting for receiver",
  "系统管理员可以在「可选功能」中开启。开启后，可以把节点上的一段端口共享给另一个面板，也可以接收其他面板共享的端口。": "A system administrator can switch it on in Optional features. Then you can share a port range on a node with another panel, or receive ports other panels share.",
  "结束端口": "Last port",
  "编辑共享 · {0}": "Edit share · {0}",
  "节点与端口": "Node and ports",
  "节点更新中": "Node updating",
  "节点监听地址（留空为全部地址）": "Listening address on the node (empty means all addresses)",
  "规则 {0}/{1}": "Rules {0}/{1}",
  "规则已提交，对方节点会自动更新。": "Rules submitted; the owner's node updates automatically.",
  "规则数已达上限": "Rule limit reached",
  "起始端口": "First port",
  "跨面板共享未开启": "Cross-panel sharing is off",
  "输入对方面板给的邀请码即可接入。你可以在共享的端口范围内建规则；规则运行在对方的节点上，流量由对方计量。": "Enter the invite code from the owner panel to join. You can create rules inside the shared port range; they run on the owner's node, which meters the traffic.",
  "输入邀请码": "Enter invite code",
  "还没有共享": "No shares yet",
  "还没有收到共享": "No received shares yet",
  "还没有规则。点「＋ 规则」在共享的端口里建一条。": "No rules yet. Click “＋ Rule” to create one in the shared ports.",
  "这个共享建立时没有流量限制": "This share was created without a traffic limit",
  "这个共享最多 {0} 条规则。删除一条，或请对方提高上限。": "This share allows at most {0} rule(s). Delete one, or ask the owner to raise the limit.",
  "这条规则由跨面板共享生成，请在「跨面板共享」页管理。": "This rule comes from a cross-panel share; manage it on the Cross-panel sharing page.",
