  "公网端还没有运行；两台服务器就绪后再设置。": "The public end is not running yet; set this once both servers are ready.",
  "这些限制作用于公网端口上的用户连接，与普通规则相同；流量计入公网服务器的流量账本。": "These limits apply to user connections on the public port, as for any rule; traffic is counted in the public server's usage ledger.",
