  "立即重置 {0} 的本周期流量？已用流量清零并从现在开始新周期，本周期的补流量一并清零，到期时间不变。": "Reset traffic for {0} now? Usage starts again in a new cycle from now, this cycle's top-ups are cleared and the expiry stays the same.",
  "流量已重置，新周期从现在开始。": "Traffic reset. A new cycle starts now.",
  "此套餐按周期重置流量：每个周期从套餐流量重新开始，未用完的流量不结转；续费只顺延到期时间。": "This plan resets traffic in cycles: each cycle starts again with the plan's traffic and unused traffic does not carry over. A renewal only extends the expiry.",
