  "每周期最多补流量次数（1..1000）": "Top-ups per cycle at most (1..1000)",
  "需要开启“套餐权益”。重置时本周期流量重新从套餐流量开始，未用完的不结转；跟随计费周期在每个已付费周期结束时重置。自动补流量需要设置流量和重置方式，用户开启后，本周期流量用完时从钱包扣款补充；补充的流量在下次重置时清零，不延长到期时间。": "Needs plan entitlements. At a reset the cycle starts again with the plan's traffic and unused traffic does not carry over. “Follows the billing period” resets at the end of every paid period. Automatic top-up needs traffic and a reset policy. When a user turns it on and the cycle's traffic runs out, the wallet is charged for a top-up; top-up traffic is cleared at the next reset and does not extend the expiry.",
