  "服务器 30 秒内没有回报当前连接，它可能正忙或刚断开；请稍后点“刷新”重试。": "The server did not report its current connections within 30 seconds; it may be busy or just disconnected. Choose “Refresh” to try again later.",
  "这台服务器的 Agent 版本过旧，不记录当前连接和拦截记录；请先升级 Agent。下方的累计统计仍然有效。": "This server's agent is too old to keep current connections and blocked connections; upgrade the agent first. The counters below are still valid.",
