  "下面是 {0} 的数据。": "Showing data from {0}.",
  "下面是 {0} 的数据，正在刷新…": "Showing data from {0}; refreshing…",
  "这台服务器的 Agent 升级后才有拦截记录。": "Blocked connections are recorded once this server's agent is upgraded.",
  "没有拦截记录。": "No blocked connections.",
  "当前连接": "Current connections",
  "累计统计（Agent 启动以来）": "Counters (since the agent started)",
  "客户端地址属于个人数据，只有能查看这台服务器配置的用户看得到。当前连接按需向服务器获取，不保存；拦截记录只保存在面板内存中，面板重启后清空。": "Client addresses are personal data; only users who may view this server's configuration see them. Current connections are fetched from the server on request and not stored; blocked connections are kept only in the panel's memory and cleared when the panel restarts.",
  "按规则筛选": "Filter by rule",
  "全部规则": "All rules",
  "这台服务器的 Agent 版本过旧，不记录拦截记录；请先升级 Agent。": "This server's agent is too old to record blocked connections; upgrade the agent first.",
  "被拒绝的连接和 UDP 会话：来源不在允许列表、达到连接数上限、配额用完、代理目的地址不允许等。同一规则、来源 IP 和原因在 60 秒内合并为一条并计数。面板保存每台服务器最近 1000 条，只在内存中，重启后清空。": "Refused connections and UDP sessions: source not in the allow list, connection limit reached, quota used up, proxy destination not allowed and so on. Refusals of the same rule, source IP and reason within 60 seconds are merged into one entry with a count. The panel keeps the latest 1000 per server, in memory only; they are cleared when it restarts.",
  "请选择测速服务器": "Choose the testing server",
  "请选择两台不同的服务器": "Choose two different servers",
  "端口必须是 1024 到 65535 之间的整数，或留空自动选择": "The port must be a whole number from 1024 to 65535, or blank to choose one automatically",
  "测速已开始，结果会显示在下方。": "Speed test started; results appear below.",
  "本次路径": "Path tested",
  "末跳是代理服务，没有固定目标：不测连接耗时": "The last hop is a proxy service with no fixed target: no connect time is measured",
  "路径上的限速（本测试不受其限制）": "Limits along the path (this test is not subject to them)",
  "限速 / 配额": "Speed limit / quota",
  "上行朝最后一跳（与客户端上传同向），下行朝入口服务器。各段依次进行，同一时间每台服务器只进行一项测速；非管理员每分钟最多发起一次。": "Upload goes towards the last hop (the way clients upload), download towards the entry server. Segments run one after another and each server runs one speed test at a time; accounts that are not administrators can start one test a minute.",
  "取消测速": "Cancel speed test",
