  "测速服务在测试中途限制了请求量，结果只包含限制之前测到的部分。": "The speed service limited requests partway through the test; the result covers only what was measured before that.",
  "speed.cloudflare.com 正在限制这台服务器的测速请求（HTTP 429），请几分钟后再试": "speed.cloudflare.com is limiting speed tests from this server (HTTP 429); try again in a few minutes",
