  "进行中": "Running",
  "已完成": "Finished",
  "路径测速…": "Path speed test…",
  "系统管理员可在「诊断报告」的“测速”中测服务器到 Cloudflare 的速度，或两台服务器之间的速度；能修改路径上每台服务器的用户可在转发规则的操作里点“路径测速…”，逐段测这条转发经过的服务器。测速流量不经过规则：不受限速，也不计入流量账本、配额和共享额度。": "System administrators measure a server against Cloudflare, or two servers against each other, under Speed test in Diagnostics. Users who may change every server of a path choose “Path speed test…” in a forwarding rule's actions to measure each server-to-server segment of it. Speed test traffic does not pass through rules: no speed limit applies, and it is not counted in the traffic ledger, quotas or shared budgets.",
  "出口代理只转发 TCP：请把传输协议设为 TCP": "An egress proxy carries TCP only: set the transport protocol to TCP",
  "出口代理只转发 TCP：请关闭 Shadowsocks 的 UDP over TCP": "An egress proxy carries TCP only: turn off Shadowsocks UDP over TCP",
  "只有 SOCKS5、HTTP CONNECT、HTTP/2 CONNECT 或 Shadowsocks 代理服务能设置出口代理": "Only a SOCKS5, HTTP CONNECT, HTTP/2 CONNECT or Shadowsocks proxy service can have an egress proxy",
