  "第 {0} 行上游代理地址无效：请写成 host:port，IPv6 地址加方括号，如 [2001:db8::1]:1080": "Upstream proxy address on line {0} is invalid: write host:port, with IPv6 addresses in brackets, such as [2001:db8::1]:1080",
  "上游代理地址 {0} 重复": "Upstream proxy address {0} is listed twice",
  "上游代理的用户名和密码必须同时填写或同时留空": "Fill in both the upstream proxy username and password, or leave both empty",
  "上游代理用户名": "The upstream proxy username",
