  "{0}须为 1 到 255 字节，不含控制字符": "{0} must be 1 to 255 bytes without control characters",
  "出口代理（经上游代理连接目的地）": "Egress proxy (reach destinations through an upstream proxy)",
  "出口代理": "Egress proxy",
  "关闭 · 本节点直接连接目的地": "Off · This node connects to destinations directly",
  "SOCKS5 · 经上游代理连接目的地": "SOCKS5 · Connect to destinations through an upstream proxy",
  "上游代理地址（host:port，每行一个，最多 8 个，按顺序尝试）": "Upstream proxy addresses (host:port, one per line, up to 8, tried in order)",
  "上游用户名（留空不认证）": "Upstream username (empty for no authentication)",
  "上游密码（与用户名同时填写）": "Upstream password (set together with the username)",
  "导入 socks5:// 链接（填入地址、用户名和密码）": "Import a socks5:// link (fills in the address, username and password)",
  "服务器 {0} 的 Agent 尚未报告支持出口代理，发布会被拒绝；请先升级 Agent。": "The agent on server {0} has not reported support for egress proxies, so publishing will be refused; upgrade the agent first.",
  "客户端 → 本节点 → 上游 SOCKS5 代理 → 目的地。目的地仍由客户端指定，并先按本规则的目的地 ACL 检查。上游地址按顺序尝试，连不上就换下一个；全部地址共用这里的用户名和密码，与入口凭据无关。只转发 TCP：规则须使用 TCP，UDP、Shadowsocks UDP over TCP 和 SOCKS5 BIND 都会被拒绝。不允许内网目的地（默认）时，域名先由本节点解析，只把检查过的 IP 发给上游；允许内网目的地且 ACL 中没有 IP 条目时，域名原样交给上游解析。": "Client → this node → upstream SOCKS5 proxy → destination. The client still chooses the destination, and this rule's destination ACL checks it first. Upstream addresses are tried in order; when one cannot be reached, the next is used. All addresses share the username and password here, which are separate from the inbound credentials. TCP only: the rule must use TCP, and UDP, Shadowsocks UDP over TCP and SOCKS5 BIND are refused. While private destinations are not allowed (the default), this node resolves domain names itself and sends only the checked IP addresses to the upstream; with private destinations allowed and no IP entries in the ACL, domain names go to the upstream unresolved.",
  "防火墙规则集": "Firewall rule sets",
  "命名的允许 / 拒绝规则集：绑定到服务器的入站、出站或单条规则，按顺序第一条匹配生效。修改后自动送达服务器，Agent 确认后生效。": "Named allow / deny rule sets bound to a server's inbound or outbound side or to single rules; the first matching rule decides. Changes reach the servers by themselves and take effect once the agent confirms.",
  "firewall acl allow deny block blacklist whitelist source destination tester 防火墙 规则集 黑名单 白名单 拦截 来源 目的地 测试": "firewall acl allow deny block blacklist whitelist source destination tester rule set",
  "服务器 {0} 的 Agent 版本过旧，不支持防火墙规则集；请先升级 Agent": "The agent on server {0} is too old for firewall rule sets; upgrade it first",
  "服务器 {0} 尚未连接面板；它的 Agent 回报后才能使用防火墙规则集": "Server {0} has not connected to the panel yet; firewall rule sets need its agent to report in first",
  "规则集 {0} 仍在使用中（{1}）；请先解除这些绑定": "Rule set {0} is still in use ({1}); remove these bindings first",
