  "规则集 {0} 属于租户；服务器只能绑定系统规则集": "Rule set {0} belongs to a tenant; servers take system rule sets",
  "规则 {0} 属于共享 {1}，共享的规则不能绑定防火墙规则集": "Rule {0} belongs to share {1}; a share's rules cannot have a firewall rule set",
  "规则 {0}：受管协议网关在协议引擎中检查客户端，不能绑定防火墙规则集": "Rule {0}: a protocol gateway checks its clients in the protocol engine and cannot take a firewall rule set",
