  "每条规则匹配客户端来源 IP 或 CIDR（IPv4 / IPv6，每条 1 到 256 个）。单个 IP 自动按 /32 或 /128 保存。": "Each rule matches client source IPs or CIDRs (IPv4 / IPv6, 1 to 256 per rule). A single IP is saved as /32 or /128.",
  "每条规则匹配目的地（IP、CIDR、域名或 *.域名，*.example.com 只匹配子域名）和/或端口（443、8000-8080）。两者都填时须同时满足。": "Each rule matches destinations (IP, CIDR, domain or *.domain; *.example.com matches subdomains only) and/or ports (443, 8000-8080). When both are set, both must match.",
