  "服务器 {0} 的 Agent 尚未报告支持防火墙规则集，绑定会被拒绝；请先升级 Agent。": "The agent on server {0} has not reported support for firewall rule sets, so binding will be refused; upgrade the agent first.",
  "连接须依次通过服务器入站规则集、规则的入站规则集和规则自身的来源列表；任何一层拒绝即拒绝。出站规则集在连接目标、代理目的地和出口代理之前检查。": "A connection must pass the server's inbound set, then the rule's inbound set, then the rule's own source lists; any layer that denies refuses it. The outbound set is checked before connecting to a target, a proxy destination or an egress proxy.",
