  "输入来源 IP，或目的地和端口，查看每一层由哪条规则决定，以及最终结果。按服务器测试时使用该服务器的期望策略，与 Agent 的判断方式相同。": "Enter a source IP, or a destination and port, to see which rule decides at each layer and the final result. Testing a server uses its desired policy, judged the same way as the agent.",
