  "规则按列表顺序检查，第一条匹配的规则决定允许或拒绝；没有规则匹配时使用默认动作。修改规则集后，所有使用它的服务器自动更新，无需重新发布配置。": "Rules are checked in list order and the first match allows or denies; when none matches, the default action applies. When a rule set changes, every server that uses it updates by itself; nothing needs publishing.",
